={{
  (() => {
    const normalizeInput = (value) =>
      String(value || '')
        .trim()
        .toLowerCase()
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .replace(/œ/g, 'oe')
        .replace(/æ/g, 'ae')
        .replace(/[’']/g, '')
        .replace(/[-_.\s]/g, '')
        .replace(/\\/g, '\\\\')
        .replace(/"/g, '\\"');

    const prenom = normalizeInput($json['Prénom']);
    const nom = normalizeInput($json.Nom);

    if (!prenom || !nom) {
      return 'FALSE()';
    }

    const airtableNormalize = (fieldName) => {
      let f = 'LOWER(TRIM({' + fieldName + '}))';

      const replacements = [
        ['é', 'e'],
        ['è', 'e'],
        ['ê', 'e'],
        ['ë', 'e'],
        ['à', 'a'],
        ['â', 'a'],
        ['ä', 'a'],
        ['î', 'i'],
        ['ï', 'i'],
        ['ô', 'o'],
        ['ö', 'o'],
        ['ù', 'u'],
        ['û', 'u'],
        ['ü', 'u'],
        ['ç', 'c'],
        ['œ', 'oe'],
        ['æ', 'ae'],
        ['’', ''],
        ["'", ''],
        [' ', ''],
        ['-', ''],
        ['_', ''],
        ['.', '']
      ];

      for (const pair of replacements) {
        const from = pair[0];
        const to = pair[1];

        f = 'SUBSTITUTE(' + f + ', "' + from + '", "' + to + '")';
      }

      return f;
    };

    const prenomField = airtableNormalize('Prénom');
    const nomField = airtableNormalize('Nom');

    return 'OR(' +
      'AND(' +
        prenomField + ' = "' + prenom + '", ' +
        nomField + ' = "' + nom + '"' +
      '), ' +
      'AND(' +
        prenomField + ' = "' + nom + '", ' +
        nomField + ' = "' + prenom + '"' +
      '), ' +
      'CONCATENATE(' + prenomField + ', ' + nomField + ') = "' + prenom + nom + '", ' +
      'CONCATENATE(' + prenomField + ', ' + nomField + ') = "' + nom + prenom + '", ' +
      'CONCATENATE(' + nomField + ', ' + prenomField + ') = "' + prenom + nom + '", ' +
      'CONCATENATE(' + nomField + ', ' + prenomField + ') = "' + nom + prenom + '"' +
    ')';
  })()
}}

