const mailItems = $('Recherche par mail').all();
const nameItems = $('Recherche par nom+prenom').all();
const loopItems = $('Loop Over Items').all();

const allItems = [
  ...mailItems.map(item => ({
    source: 'Recherche par mail',
    item
  })),
  ...nameItems.map(item => ({
    source: 'Recherche par nom+prenom',
    item
  }))
];

// Évite les doublons si les deux recherches trouvent le même record Airtable
const uniqueRecords = [];
const seenIds = new Set();

for (const entry of allItems) {
  const json = entry.item.json || {};
  const recordId = json.id || json.recordId;

  const uniqueKey = recordId || JSON.stringify(json);

  if (!seenIds.has(uniqueKey)) {
    seenIds.add(uniqueKey);
    uniqueRecords.push(entry);
  }
}

function getFields(item) {
  return item?.json?.fields || item?.json || {};
}

function hasValue(value) {
  if (value === undefined || value === null) return false;

  if (typeof value === 'string') {
    return value.trim() !== '';
  }

  if (Array.isArray(value)) {
    return value.length > 0;
  }

  if (typeof value === 'object') {
    return Object.keys(value).length > 0;
  }

  return true;
}

function getValue(primaryValue, fallbackValue) {
  if (hasValue(primaryValue)) return primaryValue;
  if (hasValue(fallbackValue)) return fallbackValue;
  return '';
}

const records = uniqueRecords.map(entry => {
  const fields = getFields(entry.item);

  return {
    source: entry.source,
    id: entry.item.json.id || entry.item.json.recordId || '',
    fields
  };
});

const recordAvecNote = records.find(record =>
  hasValue(record.fields['Note'])
);

const bestRecord = recordAvecNote || records[0] || null;
const fields = bestRecord?.fields || {};

// Données venant du Loop Over Items, utilisées seulement si les champs des Search Records sont vides
const loopFields = getFields(loopItems[0]);

const mailFinal = getValue(fields['Mail'], loopFields['Mail']);
const prenomFinal = getValue(fields['Prénom'], loopFields['Prénom']);
const nomFinal = getValue(fields['Nom'], loopFields['Nom']);

return [
  {
    json: {
      statut: recordAvecNote ? "a déjà rempli l'enquête" : "n'a pas encore rempli",
      note_existe: !!recordAvecNote,

      Mail: mailFinal,
      Prénom: prenomFinal,
      Nom: nomFinal,

      record_id: bestRecord?.id || '',
      source_match: bestRecord?.source || '',
      nombre_records_trouves: records.length,
      sources_trouvees: [...new Set(records.map(record => record.source))]
    }
  }
];
